<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import { Page } from '@vben/common-ui'; import { listPlatformSeckillApi, type PlatformSeckillActive } from '#/api/core/platform-seckill';
const loading = ref(false); const rows = ref<PlatformSeckillActive[]>([]); const total = ref(0); const query = reactive({ limit: 20, mer_id: undefined as number | undefined, page: 1 });
async function load() { loading.value = true; try { const data = await listPlatformSeckillApi(query); rows.value = data.list || []; total.value = data.total || 0; } finally { loading.value = false; } } onMounted(() => void load());
</script><template><Page title="秒杀监管" description="监管各商户秒杀活动；当前接入真实只读列表，活动编辑和删除将在平台独立权限完成后开放。"><el-card shadow="never"><el-form inline><el-form-item label="商户 ID"><el-input-number v-model="query.mer_id" :min="1" /></el-form-item><el-button type="primary" @click="query.page=1;load()">查询</el-button></el-form><el-table v-loading="loading" :data="rows"><el-table-column label="活动" min-width="160" prop="name" /><el-table-column label="商户" min-width="130"><template #default="{row}">{{ row.mer_name || `商户 #${row.mer_id}` }}</template></el-table-column><el-table-column label="商品" min-width="150"><template #default="{row}">{{ row.store_name || `商品 #${row.product_id}` }}</template></el-table-column><el-table-column label="秒杀价" width="110"><template #default="{row}">¥{{ Number(row.seckill_price).toFixed(2) }}</template></el-table-column><el-table-column label="活动日期" min-width="200"><template #default="{row}">{{ row.start_day }} 至 {{ row.end_day }}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status===1?'success':'info'">{{ row.status===1?'启用':'停用' }}</el-tag></template></el-table-column></el-table><div class="mt-4 flex justify-end"><el-pagination :current-page="query.page" :page-size="query.limit" :total="total" layout="total, prev, pager, next" @current-change="(page)=>{query.page=page;load()}" /></div></el-card></Page></template>
